import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Activity as ActivityIcon, ArrowDownLeft, ArrowRight, ArrowUpRight, Bell, Bot, Check, CheckCheck, ChevronRight, CircleHelp, Clock3, Cpu, Database, Eye, FileCheck2, Fingerprint, GitBranch, HardDrive, LayoutDashboard, ListTodo, LoaderCircle, LockKeyhole, Menu, MessageSquare, Pause, Play, RefreshCw, Search, Server, Settings2, ShieldCheck, Square, Terminal, TrendingUp, Wifi, X, XCircle } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import type { Activity, Agent, Approval, ControlAction, Section, State, Task, UsageRow } from './types';

const sections: { name: Section; icon: LucideIcon }[] = [
  { name: 'Overview', icon: LayoutDashboard }, { name: 'Agents', icon: Bot }, { name: 'Tasks', icon: ListTodo }, { name: 'Token Usage', icon: TrendingUp }, { name: 'Approvals', icon: ShieldCheck }, { name: 'Activity', icon: ActivityIcon }, { name: 'Git & Testing', icon: GitBranch }, { name: 'Infrastructure', icon: Server }, { name: 'Settings', icon: Settings2 },
];
const numeric = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value);
const count = (value: unknown) => numeric(value) ? value.toLocaleString('en-US') : 'Unavailable';
const words = (value?: string | null) => value ? value.replace(/[_-]/g, ' ').replace(/\b\w/g, letter => letter.toUpperCase()) : 'Unavailable';
const short = (value?: string | null, size = 12) => value ? value.length > size ? `${value.slice(0, size)}…` : value : 'Not reported';
const duration = (value?: number | null) => !numeric(value) ? 'Unavailable' : value < 60 ? `${Math.round(value)}s` : value < 3600 ? `${Math.floor(value / 60)}m ${Math.floor(value % 60)}s` : value < 86400 ? `${Math.floor(value / 3600)}h ${Math.floor(value % 3600 / 60)}m` : `${Math.floor(value / 86400)}d ${Math.floor(value % 86400 / 3600)}h`;
const bytes = (value?: number | null) => !numeric(value) ? 'Unavailable' : value >= 1024 ** 3 ? `${(value / 1024 ** 3).toFixed(1)} GB` : `${(value / 1024 ** 2).toFixed(0)} MB`;
function timeAgo(value?: string | null) { if (!value || !Number.isFinite(Date.parse(value))) return 'Not reported'; const seconds = Math.max(0, (Date.now() - Date.parse(value)) / 1000); return seconds < 10 ? 'Just now' : seconds < 60 ? `${Math.floor(seconds)}s ago` : seconds < 3600 ? `${Math.floor(seconds / 60)}m ago` : seconds < 86400 ? `${Math.floor(seconds / 3600)}h ago` : `${Math.floor(seconds / 86400)}d ago`; }
const dateTime = (value?: string | null) => value && Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : 'Not reported';
const sha = (value?: string | null): value is string => Boolean(value && /^[a-f0-9]{64}$/.test(value));

function Brand({ compact = false }: { compact?: boolean }) { return <div className={`brand ${compact ? 'brand-compact' : ''}`}><span className="brand-mark" aria-hidden="true"><span /><span /><span /></span><span><strong>Agent Control</strong><small>FANTASY EVOLUTION</small></span></div>; }
function Badge({ status, label }: { status?: string | null; label?: string }) { const state = (status ?? 'unavailable').toLowerCase().replaceAll(' ', '_'); const tone = ['running', 'healthy', 'online', 'available', 'passed', 'completed', 'connected', 'authenticated', 'source_recorded'].includes(state) ? 'good' : ['failed', 'error', 'emergency_stop', 'critical', 'rejected', 'unhealthy'].includes(state) ? 'bad' : ['paused', 'blocked', 'approval_required', 'rate_limited', 'waiting', 'pending', 'stale', 'interrupted'].includes(state) ? 'warn' : 'neutral'; return <span className={`badge badge-${tone}`}><span className="status-dot" />{label ?? words(status)}</span>; }
function Empty({ icon: Icon = Eye, title, children }: { icon?: LucideIcon; title: string; children?: React.ReactNode }) { return <div className="empty"><span className="empty-icon"><Icon size={23} /></span><strong>{title}</strong>{children && <p>{children}</p>}</div>; }
function Panel({ title, subtitle, children, action, className = '' }: { title: string; subtitle?: string; children: React.ReactNode; action?: React.ReactNode; className?: string }) { return <section className={`panel ${className}`}><div className="panel-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>{children}</section>; }
function Metric({ label, value, detail, icon: Icon, accent = false }: { label: string; value: React.ReactNode; detail: string; icon: LucideIcon; accent?: boolean }) { return <div className={`metric ${accent ? 'metric-accent' : ''}`}><div className="metric-label">{label}<Icon size={17} /></div><strong className={value === 'Unavailable' ? 'metric-unavailable' : ''}>{value}</strong><p>{detail}</p></div>; }
function Detail({ label, children }: { label: string; children?: React.ReactNode }) { return <div className="detail"><span>{label}</span><strong>{children ?? 'Unavailable'}</strong></div>; }
function Note({ children, warning = false }: { children: React.ReactNode; warning?: boolean }) { return <div className={`note ${warning ? 'note-warning' : ''}`}><CircleHelp size={17} /><span>{children}</span></div>; }
function Modal({ title, children, close }: { title: string; children: React.ReactNode; close: () => void }) { const panel = useRef<HTMLDivElement>(null); useEffect(() => { const previous = document.activeElement as HTMLElement | null; panel.current?.focus(); const key = (event: KeyboardEvent) => { if (event.key === 'Escape') close(); if (event.key === 'Tab') { const nodes = panel.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,[tabindex="0"]'); if (!nodes?.length) return; const first = nodes[0], last = nodes[nodes.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } } }; document.addEventListener('keydown', key); return () => { document.removeEventListener('keydown', key); previous?.focus(); }; }, [close]); return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) close(); }}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabIndex={-1} ref={panel}><div className="modal-heading"><h2 id="modal-title">{title}</h2><button className="icon-button" onClick={close} aria-label="Close dialog"><X size={20} /></button></div>{children}</div></div>; }

export default function App() {
  const [authenticated, setAuthenticated] = useState(false), [booting, setBooting] = useState(true), [csrf, setCsrf] = useState(''), [password, setPassword] = useState(''), [loginError, setLoginError] = useState(''), [loginBusy, setLoginBusy] = useState(false);
  const [data, setData] = useState<State | null>(null), [section, setSection] = useState<Section>('Overview'), [sidebar, setSidebar] = useState(false), [loading, setLoading] = useState(false), [error, setError] = useState(''), [busy, setBusy] = useState(false), [toast, setToast] = useState('');
  const [dialog, setDialog] = useState<'start' | 'resume' | null>(null), [acknowledge, setAcknowledge] = useState(false);
  const inFlight = useRef(false), mutation = useRef(false);
  const session = useCallback(async () => { setBooting(true); try { const response = await fetch('/api/session', { credentials: 'same-origin', cache: 'no-store' }); if (!response.ok) { if (response.status !== 401) setLoginError('The local service could not verify this session.'); setAuthenticated(false); return; } const result = await response.json(); if (typeof result.csrfToken !== 'string') throw Error(); setCsrf(result.csrfToken); setAuthenticated(true); setLoginError(''); } catch { setLoginError('Cannot reach the local control service. Check that it is running, then retry.'); } finally { setBooting(false); } }, []);
  useEffect(() => { const timer = setTimeout(() => void session(), 0); return () => clearTimeout(timer); }, [session]);
  const refresh = useCallback(async () => { if (inFlight.current) return; inFlight.current = true; setLoading(true); try { const response = await fetch('/api/state', { credentials: 'same-origin', cache: 'no-store' }); if (response.status === 401) { setAuthenticated(false); setCsrf(''); setData(null); return; } if (!response.ok) throw Error(); const result = await response.json(); setData(result as State); setError(''); } catch { setError('The local service is unavailable. Showing the last observation; controls are paused until the connection returns.'); } finally { inFlight.current = false; setLoading(false); } }, []);
  useEffect(() => { if (!authenticated) return; const initial = setTimeout(() => void refresh(), 0); const timer = setInterval(() => void refresh(), 10000); return () => { clearTimeout(initial); clearInterval(timer); }; }, [authenticated, refresh]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 6500); return () => clearTimeout(timer); }, [toast]);
  async function login(event: React.FormEvent) { event.preventDefault(); if (loginBusy) return; setLoginBusy(true); setLoginError(''); try { const response = await fetch('/api/login', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }) }); const result = await response.json(); if (!response.ok || typeof result.csrfToken !== 'string') throw Error(typeof result.error === 'string' ? result.error : 'Sign in failed.'); setCsrf(result.csrfToken); setAuthenticated(true); } catch (cause) { setLoginError(cause instanceof Error ? cause.message.slice(0, 300) : 'Could not sign in.'); } finally { setPassword(''); setLoginBusy(false); } }
  const allowed = (action: string) => Boolean(data && !error && !busy && data.capabilities?.controls?.includes(action));
  async function control(action: ControlAction, values: Record<string, unknown> = {}) { if (mutation.current || !csrf || !allowed(action)) return false; mutation.current = true; setBusy(true); try { const response = await fetch('/api/control', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, body: JSON.stringify({ action, ...values }) }); const result = await response.json(); if (response.status === 401) { setAuthenticated(false); setCsrf(''); throw Error('Your local session expired. Sign in again.'); } if (!response.ok) throw Error(typeof result.error === 'string' ? result.error : 'The control request was refused.'); setToast(action === 'start' ? 'Bounded cycle requested. Watch activity for its actual outcome.' : action === 'approve' || action === 'reject' ? 'The exact-target decision was recorded.' : action === 'guidance' ? 'Guidance saved for unclaimed work.' : 'Control request recorded.'); await refresh(); return true; } catch (cause) { setToast(cause instanceof Error ? cause.message.slice(0, 400) : 'The request could not be completed.'); return false; } finally { mutation.current = false; setBusy(false); } }
  async function lockWorkspace() { try { const response = await fetch('/api/logout', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf }, body: '{}' }); if (!response.ok) throw Error(); setCsrf(''); setPassword(''); setData(null); setAuthenticated(false); } catch { setToast('The local session could not be locked. Retry when the service returns.'); } }
  function navigate(next: Section) { setSection(next); setSidebar(false); }
  const tasks = data?.automation?.tasks ?? [], runs = data?.agents ?? [], approvals = data?.approvals ?? [], activity = data?.activity ?? [], pending = approvals.filter(row => row.status === 'pending'), mode = data?.automation?.mode;
  const closeDialog = useCallback(() => { setDialog(null); setAcknowledge(false); }, []);
  if (booting) return <div className="boot-screen"><Brand /><LoaderCircle className="spin" size={24} /><p>Connecting to your local workspace…</p></div>;
  if (!authenticated) return <div className="login-shell"><div className="login-intro"><Brand /><div className="login-copy"><span className="eyebrow">YOUR LOCAL OPERATIONS WORKSPACE</span><h1>Clear oversight.<br /><em>Controlled execution.</em></h1><p>Follow the work, inspect the evidence, and keep every important decision in your hands.</p><div className="login-principles"><span><LockKeyhole size={17} /> Loopback only</span><span><ShieldCheck size={17} /> Explicit approvals</span><span><Database size={17} /> Persistent local records</span></div></div><span className="login-footer">Independent of the Fantasy Evolution application.</span></div><main className="login-main"><form className="login-card" onSubmit={login}><span className="login-lock"><LockKeyhole size={24} /></span><h2>Open Control Center</h2><p>Open the private owner-password.txt file locally and enter its password. The service never returns it through an API.</p><label htmlFor="control-password">Local password</label><input id="control-password" type="password" value={password} onChange={event => setPassword(event.target.value)} autoComplete="current-password" required autoFocus placeholder="Enter your local password" />{loginError && <div className="form-error" role="alert">{loginError}</div>}<button className="button button-primary login-submit" disabled={loginBusy || !password}>{loginBusy ? <LoaderCircle className="spin" size={17} /> : <>Unlock workspace <ArrowRight size={17} /></>}</button><small><ShieldCheck size={14} /> Passwords and session tokens are not stored by this interface.</small>{loginError && <button className="text-button" type="button" onClick={() => void session()}>Retry local connection</button>}</form></main></div>;
  return <div className="app-shell">
    {sidebar && <button className="sidebar-scrim" aria-label="Close navigation" onClick={() => setSidebar(false)} />}
    <aside className={`sidebar ${sidebar ? 'sidebar-open' : ''}`}><Brand /><div className="workspace-label"><span className="workspace-dot" />LOCAL WORKSPACE</div><nav aria-label="Main navigation">{sections.map(({ name, icon: Icon }) => <button className={`nav-item ${section === name ? 'nav-active' : ''}`} key={name} onClick={() => navigate(name)} aria-current={section === name ? 'page' : undefined}><Icon size={18} /><span>{name}</span>{name === 'Approvals' && pending.length > 0 && <span className="nav-count">{pending.length}</span>}</button>)}</nav><div className="sidebar-footer"><div className="spend-policy"><ShieldCheck size={17} /><span>No additional spending<small>Existing subscription only</small></span></div><div className="local-address"><span className="status-dot" />{data?.settings?.port ? `127.0.0.1:${data.settings.port}` : 'Loopback connection'}</div></div></aside>
    <div className="workspace"><header className="topbar"><div className="topbar-left"><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setSidebar(true)}><Menu size={21} /></button><span className="breadcrumb-project">Workspace</span><ChevronRight size={14} /><strong>{section}</strong></div><div className="topbar-right"><span className="refresh-label">{error ? 'Connection interrupted' : data ? `Updated ${timeAgo(data.generatedAt).toLowerCase()}` : 'Awaiting observation'}</span><button className="icon-button" title="Refresh local state; no model call" aria-label="Refresh state" onClick={() => void refresh()} disabled={loading}><RefreshCw size={17} className={loading ? 'spin' : ''} /></button><button className="session-pill session-lock" onClick={() => void lockWorkspace()} title="End only this Control Center session"><LockKeyhole size={13} /> Lock workspace</button></div></header>
      <main className="main-content"><div className="page-heading"><div><span className="eyebrow">FANTASY EVOLUTION / OPERATIONS</span><h1>{section === 'Overview' ? 'Workspace overview' : section}</h1><p>{({ Overview: 'A clear view of the work, the evidence, and what needs your attention.', Agents: 'Observed executions and prepared roles, with honest availability and liveness.', Tasks: 'Priorities, dependencies, and reviewed handoffs from the persistent queue.', 'Token Usage': 'Recorded activity from supported telemetry. Never an estimated subscription balance.', Approvals: 'Human decisions bound to exact actions, fingerprints, and expiration.', Activity: 'Meaningful local events and an audit trail of control actions.', 'Git & Testing': 'Local tracking state, checkpoints, and recorded verification evidence.', Infrastructure: 'Observed host and service health. Missing or stale readings remain explicit.', Settings: 'Execution boundaries, local access, and the zero-additional-spending policy.' } as Record<Section, string>)[section]}</p></div><Badge status={mode} label={mode ? `${words(mode)} mode` : 'Mode unavailable'} /></div>
        {error && <div className="connection-banner" role="status"><Wifi size={18} /><span>{error}</span><button className="text-button" onClick={() => void refresh()}>Retry</button></div>}
        {!data ? <div className="loading-grid" aria-busy="true" aria-label="Loading actual workspace state"><div /><div /><div /><div /><div /></div> : <>
          {section === 'Overview' && <><div className="control-strip"><div><span className={`control-indicator ${mode === 'emergency_stop' ? 'indicator-danger' : ''}`} /><div><strong>{mode === 'emergency_stop' ? 'Emergency stop is active' : mode === 'paused' ? 'New work is paused' : 'Bounded execution. Explicit authority.'}</strong><span>{data.capabilities?.writableExecution ? 'See the current approved execution policy.' : 'Read-only reviews and implementation handoffs. No automatic integration.'}</span></div></div><div className="button-row"><button className="button button-primary" disabled={!allowed('start')} onClick={() => setDialog('start')}><Play size={15} /> Run bounded cycle</button>{mode === 'paused' || mode === 'emergency_stop' ? <button className="button" disabled={!allowed('resume')} onClick={() => mode === 'emergency_stop' ? setDialog('resume') : void control('resume', { acknowledgeStop: false })}><Play size={15} /> Resume</button> : <button className="button" disabled={!allowed('pause')} onClick={() => void control('pause')}><Pause size={15} /> Pause</button>}<button className="button button-danger" disabled={!allowed('stop')} onClick={() => void control('stop')}><Square size={14} /> Emergency stop</button></div></div><div className="metrics-grid"><Metric label="Verified managed agents" value={data.coverage?.processLivenessVerified ? count(runs.filter(row => row.active === true).length) : 'Unavailable'} detail={data.coverage?.processLivenessVerified ? 'Based on verified process observations' : 'Execution records do not prove process liveness'} icon={Bot} /><Metric label="Recorded tokens" value={count(data.usage?.totalTokens)} detail="Input + output; cached tokens are a subset" icon={TrendingUp} accent /><Metric label="Ready queue records" value={count(tasks.filter(row => row.status === 'ready').length)} detail={`${tasks.length} task records · dependencies still apply`} icon={ListTodo} /><Metric label="Awaiting decisions" value={count(pending.length)} detail="Exact targets awaiting owner review" icon={ShieldCheck} /></div><div className="overview-grid"><Panel title="Work queue" subtitle="Current priorities from the persistent task records" action={<button className="text-button" onClick={() => navigate('Tasks')}>View all <ArrowRight size={14} /></button>}><TaskTable tasks={[...tasks].sort((a, b) => (a.priority ?? 1000) - (b.priority ?? 1000)).slice(0, 6)} compact /></Panel><Panel title="Attention inbox" subtitle="Decisions and meaningful blockers" action={<span className="small-counter">{pending.length}</span>}>{pending.length ? <div className="attention-list">{pending.slice(0, 3).map(row => <button className="attention-item" key={row.id} onClick={() => navigate('Approvals')}><span className="attention-icon"><ShieldCheck size={18} /></span><span><strong>{row.exact_proposed_action ?? row.id}</strong><small>{row.id} · {sha(row.target_fingerprint) ? 'Exact target prepared' : 'Target not yet bound'}</small></span><ChevronRight size={15} /></button>)}</div> : <Empty icon={CheckCheck} title="No pending approval records">New decisions appear here when an exact proposal needs your review.</Empty>}<div className="panel-bottom-note"><LockKeyhole size={13} /> Decisions never activate a scheduler by themselves.</div></Panel><Panel title="Recorded execution activity" subtitle="Configured roles are not counted as active sessions" action={<button className="text-button" onClick={() => navigate('Agents')}>Inspect agents <ArrowRight size={14} /></button>}><AgentTable runs={runs.slice(0, 4)} compact /></Panel><Panel title="Latest activity" subtitle="Sanitized events from the local audit trail" action={<button className="icon-button" aria-label="View all activity" onClick={() => navigate('Activity')}><ArrowUpRight size={17} /></button>}><ActivityList events={activity.slice(0, 5)} /></Panel></div><div className="overview-footer"><span><ShieldCheck size={15} /> Additional spending authorization: $0</span><span><Terminal size={15} /> Status refresh never invokes a model</span><span><GitBranch size={15} /> {data.git?.branch ?? 'Branch unavailable'} · {short(data.git?.commit, 8)}</span></div></>}
          {section === 'Agents' && <AgentsView data={data} allowed={allowed} control={control} />}
          {section === 'Tasks' && <TasksView tasks={tasks} allowed={allowed} control={control} />}
          {section === 'Token Usage' && <UsageView data={data} />}
          {section === 'Approvals' && <ApprovalsView approvals={approvals} allowed={allowed} control={control} />}
          {section === 'Activity' && <Panel title="Activity timeline" subtitle="Persistent, sanitized observations and control decisions"><ActivityList events={activity} /></Panel>}
          {section === 'Git & Testing' && <GitView data={data} />}
          {section === 'Infrastructure' && <InfrastructureView data={data} />}
          {section === 'Settings' && <SettingsView data={data} allowed={allowed} control={control} />}
        </>}
      </main><footer className="page-footer"><span><LockKeyhole size={12} /> Private local control plane</span><span>Recorded evidence. No invented live metrics.</span></footer></div>
    {toast && <div className="toast" role="status"><Bell size={17} /><span>{toast}</span><button className="icon-button" aria-label="Dismiss notification" onClick={() => setToast('')}><X size={15} /></button></div>}
    {dialog && <Modal title={dialog === 'start' ? 'Run one bounded cycle' : 'Resume after emergency stop'} close={closeDialog}>{dialog === 'start' ? <><p className="modal-description">Use the existing ChatGPT subscription for at most one read-only review, bounded to {data?.settings?.executionTimeoutSeconds ?? 180} seconds. Implementation work remains a reviewed handoff.</p><Note>No additional spending, writable execution, or unattended scheduling will be enabled.</Note><div className="modal-actions"><button className="button" onClick={closeDialog}>Cancel</button><button className="button button-primary" disabled={!allowed('start')} onClick={async () => { if (await control('start', { confirmed: true })) closeDialog(); }}><Play size={15} /> Start bounded cycle</button></div></> : <><p className="modal-description">This returns the controller to assisted mode. It does not reset task attempts, erase failures, or enable unattended work.</p><label className="checkbox-label"><input type="checkbox" checked={acknowledge} onChange={event => setAcknowledge(event.target.checked)} /><span>I acknowledge the emergency stop and want to resume assisted operation.</span></label><div className="modal-actions"><button className="button" onClick={closeDialog}>Keep stopped</button><button className="button button-primary" disabled={!acknowledge || !allowed('resume')} onClick={async () => { if (await control('resume', { acknowledgeStop: true })) closeDialog(); }}>Resume assisted mode</button></div></>}</Modal>}
  </div>;
}

type ControlProps = { allowed: (action: string) => boolean; control: (action: ControlAction, values?: Record<string, unknown>) => Promise<boolean> };
function TaskTable({ tasks, compact = false, onSelect }: { tasks: Task[]; compact?: boolean; onSelect?: (task: Task) => void }) { if (!tasks.length) return <Empty icon={ListTodo} title="No task records">Tasks appear here after the owner-maintained queue is available.</Empty>; return <div className="table-scroll"><table><thead><tr><th>Task</th>{!compact && <th>Role / milestone</th>}<th>State</th><th>Priority</th>{!compact && <th>Attempts</th>}</tr></thead><tbody>{tasks.map(task => <tr key={task.id}><td>{onSelect ? <button className="table-task-button" onClick={() => onSelect(task)}><span className="task-id">{task.id}</span><strong>{task.title}</strong></button> : <><span className="task-id">{task.id}</span><strong className="table-task-title">{task.title}</strong></>}</td>{!compact && <td><span>{words(task.assigned_role)}</span><small>{task.milestone ?? 'Milestone unavailable'}</small></td>}<td><Badge status={task.status} /></td><td><span className="priority-tag">{numeric(task.priority) ? `P${task.priority}` : '—'}</span></td>{!compact && <td>{count(task.attempt_count)}</td>}</tr>)}</tbody></table></div>; }
function AgentTable({ runs, compact = false, select }: { runs: Agent[]; compact?: boolean; select?: (run: Agent) => void }) { if (!runs.length) return <Empty icon={Bot} title="No observed execution records">Configured roles do not create activity. Actual retained runs will appear here.</Empty>; return <div className="table-scroll"><table><thead><tr><th>Execution</th><th>Observed state</th>{!compact && <th>Model / task</th>}<th>{compact ? 'Runtime' : 'Last observation'}</th></tr></thead><tbody>{runs.map((run, index) => <tr key={run.runId ?? run.sessionId ?? index}><td><div className="agent-cell"><span className="agent-avatar"><Bot size={17} /></span><span>{select ? <button className="table-link" onClick={() => select(run)}>{run.role ? words(run.role) : 'Role not reported'}</button> : <strong>{run.role ? words(run.role) : 'Observed execution'}</strong>}<small className="mono">{short(run.sessionId ?? run.runId, 16)}</small></span></div></td><td><Badge status={run.state} label={run.state === 'running' && run.active !== true ? 'Running · unverified' : undefined} /></td>{!compact && <td>{run.model ?? 'Model unavailable'}<small>{run.taskId ?? 'Task not reported'}</small></td>}<td className="nowrap">{compact ? duration(run.elapsedSeconds) : timeAgo(run.lastObservedAt)}</td></tr>)}</tbody></table></div>; }
function ActivityList({ events }: { events: Activity[] }) { if (!events.length) return <Empty icon={ActivityIcon} title="No recorded activity">Only actual observations and meaningful control actions are shown.</Empty>; return <div className="activity-list">{events.map((event, index) => <div className="activity-item" key={`${event.id}-${index}`}><span className={`activity-dot ${event.severity === 'critical' || event.severity === 'error' ? 'activity-danger' : event.severity === 'warning' ? 'activity-warning' : ''}`} /><div><strong>{event.summary ?? words(event.kind)}</strong><span>{words(event.kind)}</span></div><time title={dateTime(event.at)}>{timeAgo(event.at)}</time></div>)}</div>; }

function AgentsView({ data, allowed, control }: { data: State } & ControlProps) { const [search, setSearch] = useState(''), [selected, setSelected] = useState<Agent | null>(null); const runs = (data.agents ?? []).filter(run => [run.role, run.sessionId, run.runId, run.taskId, run.model].some(value => value?.toLowerCase().includes(search.toLowerCase()))); const close = useCallback(() => setSelected(null), []); return <><Note>Live process state is {data.coverage?.processLivenessVerified ? 'verified by the reported collector' : 'not verified by this collector'}. Liveness is scoped to managed controller receipts. Persisted sessions and configured roles alone never prove an agent is active.</Note><Panel title="Observed executions" subtitle={`${count(data.agents?.length)} recorded runs; showing up to 100 matching records`} action={<label className="search-field"><Search size={16} /><input aria-label="Search executions" placeholder="Search role, session, task…" value={search} onChange={event => setSearch(event.target.value)} /></label>}><AgentTable runs={runs.slice(0, 100)} select={setSelected} /></Panel><div className="section-heading"><div><span className="eyebrow">AVAILABLE RESPONSIBILITIES</span><h2>Configured roles</h2><p>Prepared instructions, not running agents.</p></div><span className="small-counter">{count(data.roles?.length)}</span></div><div className="roles-grid">{data.roles?.length ? data.roles.map(role => <div className="role-card" key={role.name}><span className="role-icon"><Bot size={20} /></span><Badge status="configured" /><h3>{words(role.name)}</h3><p>{role.description ?? 'Prepared role instructions; no execution implied.'}</p></div>) : <Empty title="Role configuration unavailable" />}</div>{selected && <Modal title="Observed execution details" close={close}><div className="detail-grid"><Detail label="Session"><code>{selected.sessionId ?? 'Not reported'}</code></Detail><Detail label="Parent session"><code>{selected.parentSessionId ?? 'Not reported'}</code></Detail><Detail label="Run"><code>{selected.runId ?? 'Not reported'}</code></Detail><Detail label="Role">{words(selected.role)}</Detail><Detail label="Milestone">{selected.milestone ?? 'Not reported'}</Detail><Detail label="State"><Badge status={selected.state} /></Detail><Detail label="Task">{selected.taskId ?? 'Not reported'}</Detail><Detail label="Model">{selected.model ?? 'Unavailable'}</Detail><Detail label="Reasoning">{selected.reasoning ?? 'Unavailable'}</Detail><Detail label="Started">{dateTime(selected.startedAt)}</Detail><Detail label="Runtime">{duration(selected.elapsedSeconds)}</Detail><Detail label="Last observed">{dateTime(selected.lastObservedAt)}</Detail><Detail label="Tokens">{count(selected.usage?.totalTokens)}</Detail><Detail label="Worktree"><code>{selected.worktree ?? 'Not reported'}</code></Detail><Detail label="Branch">{selected.branch ?? 'Not reported'}</Detail><Detail label="Commit"><code>{selected.commit ?? 'Not reported'}</code></Detail><Detail label="Retries / failures">{count(selected.retries)} / {count(selected.failures)}</Detail></div>{selected.intervention && <Note warning>{selected.intervention}</Note>}<div className="modal-actions"><button className="button" onClick={close}>Close</button><button className="button button-danger" disabled={!allowed('cancel') || selected.managed !== true || selected.active !== true || !selected.runId} onClick={() => void control('cancel', { runId: selected.runId })}><Square size={14} /> Cancel managed run</button></div><small className="muted">Cancellation is available only for a verified, owned managed process.</small></Modal>}</>; }

function TasksView({ tasks, allowed, control }: { tasks: Task[] } & ControlProps) { const [query, setQuery] = useState(''), [filter, setFilter] = useState('all'), [selected, setSelected] = useState<Task | null>(null), [priority, setPriority] = useState(''), [guidance, setGuidance] = useState(''); const close = useCallback(() => setSelected(null), []); const visible = tasks.filter(task => (filter === 'all' || task.status === filter) && `${task.id} ${task.title} ${task.assigned_role}`.toLowerCase().includes(query.toLowerCase())); const claimed = selected?.status === 'running' || selected?.status === 'verification'; return <><div className="filter-toolbar"><label className="search-field"><Search size={16} /><input aria-label="Search tasks" placeholder="Search tasks or roles…" value={query} onChange={event => setQuery(event.target.value)} /></label><select aria-label="Filter task status" value={filter} onChange={event => setFilter(event.target.value)}><option value="all">All states</option>{['ready', 'running', 'verification', 'completed', 'failed', 'blocked', 'approval_required', 'paused'].map(state => <option key={state} value={state}>{words(state)}</option>)}</select><span className="muted">{visible.length} records</span></div><Panel title="Persistent task queue" subtitle="Task claims, dependency gates, and acceptance evidence remain authoritative"><TaskTable tasks={visible} onSelect={task => { setSelected(task); setPriority(String(task.priority ?? '')); setGuidance(''); }} /></Panel>{selected && <Modal title={selected.id} close={close}><h3>{selected.title}</h3><p className="modal-description">{selected.description ?? 'No description recorded.'}</p><div className="detail-grid"><Detail label="State"><Badge status={selected.status} /></Detail><Detail label="Role">{words(selected.assigned_role)}</Detail><Detail label="Milestone">{selected.milestone}</Detail><Detail label="Execution kind">{words(selected.execution_kind)}</Detail><Detail label="Dependencies">{selected.dependencies?.length ? selected.dependencies.join(', ') : 'None recorded'}</Detail><Detail label="Attempts">{count(selected.attempt_count)}</Detail><Detail label="Last execution">{dateTime(selected.last_execution_time)}</Detail><Detail label="Commit"><code>{selected.associated_commit ?? 'Not reported'}</code></Detail></div>{selected.blocker_classification && <Note warning>{words(selected.blocker_classification)}</Note>}<form className="stacked-form" onSubmit={async event => { event.preventDefault(); if (numeric(Number(priority)) && await control('prioritize', { taskId: selected.id, priority: Number(priority) })) close(); }}><label htmlFor="task-priority">Priority <span>Lower numbers run first</span></label><div className="input-action"><input id="task-priority" type="number" min="0" max="1000" required value={priority} onChange={event => setPriority(event.target.value)} /><button className="button" disabled={!allowed('prioritize') || claimed}>Update priority</button></div></form><form className="stacked-form" onSubmit={async event => { event.preventDefault(); if (await control('guidance', { taskId: selected.id, guidance: guidance.trim(), ...(selected.definition_fingerprint || selected.taskFingerprint ? { taskExpectedFingerprint: selected.definition_fingerprint ?? selected.taskFingerprint } : {}) })) close(); }}><label htmlFor="task-guidance">Owner guidance</label><textarea id="task-guidance" rows={3} maxLength={4000} required value={guidance} onChange={event => setGuidance(event.target.value)} placeholder="Add direction for future unclaimed work…" /><small className="muted">Running or already claimed work cannot be silently rewritten.</small><button className="button button-primary" disabled={!allowed('guidance') || claimed || !guidance.trim()}><MessageSquare size={15} /> Save guidance</button></form></Modal>}</>; }

function UsageTable({ rows, label }: { rows?: UsageRow[]; label: string }) { if (!rows?.length) return <Empty icon={TrendingUp} title={`No ${label.toLowerCase()} breakdown recorded`}>Unavailable telemetry is never filled with estimates.</Empty>; return <div className="table-scroll"><table><thead><tr><th>{label}</th><th>Input</th><th>Cached input</th><th>Output</th><th>Reasoning</th><th>Total</th></tr></thead><tbody>{rows.slice(0, 60).map((row, index) => <tr key={row.id ?? row.sessionId ?? index}><td className="mono" title={row.id ?? row.sessionId}>{short(row.id ?? row.sessionId, 30)}</td><td>{count(row.inputTokens)}</td><td>{count(row.cachedInputTokens)}</td><td>{count(row.outputTokens)}</td><td>{count(row.reasoningTokens)}</td><td className="strong">{count(row.totalTokens)}</td></tr>)}</tbody></table></div>; }
function UsageView({ data }: { data: State }) { const [tab, setTab] = useState<'Turn' | 'Session' | 'Task' | 'Agent'>('Session'); const usage = data.usage; return <><div className="metrics-grid"><Metric label="Recorded total" value={count(usage?.totalTokens)} detail="Input + output across retained coverage" icon={TrendingUp} accent /><Metric label="Input tokens" value={count(usage?.inputTokens)} detail="Includes the cached input subset" icon={ArrowDownLeft} /><Metric label="Output tokens" value={count(usage?.outputTokens)} detail="Reasoning is not added a second time" icon={ArrowUpRight} /><Metric label="Cached input" value={count(usage?.cachedInputTokens)} detail="A subset of input, not extra consumption" icon={Database} /></div><div className="two-column"><Panel title="Recorded consumption" subtitle="Period totals from deduplicated observed events"><div className="period-row"><span className="period-icon"><Clock3 size={20} /></span><span>Last 24 hours<small>Timestamped per-turn coverage only</small></span><strong>{count(usage?.daily?.totalTokens)}</strong></div><div className="period-row"><span className="period-icon"><ActivityIcon size={20} /></span><span>Last 7 days<small>Timestamped per-turn coverage only</small></span><strong>{count(usage?.weekly?.totalTokens)}</strong></div><div className="period-row"><span className="period-icon"><Database size={20} /></span><span>Lifetime recorded<small>Not an account-wide billing total</small></span><strong>{count(usage?.totalTokens)}</strong></div><div className="mini-metrics"><div><strong>{count(usage?.sessions)}</strong><span>Recorded sessions</span></div><div><strong>{count(usage?.turns)}</strong><span>Observed turns</span></div><div><strong>{count(usage?.reasoningTokens)}</strong><span>Reasoning tokens</span></div></div></Panel><Panel title="Subscription visibility" subtitle="Account limits are shown only when actually exposed"><Detail label="Remaining allowance">{count(usage?.subscriptionRemaining)}</Detail><Detail label="Current context utilization">{numeric(usage?.currentContextUtilization ?? usage?.contextUtilization) ? `${usage?.currentContextUtilization ?? usage?.contextUtilization}%` : 'Unavailable'}</Detail><Detail label="Subscription authentication">{usage?.rateLimits?.authenticationMethod ?? 'Unavailable'}</Detail>{(['primary', 'secondary'] as const).map(window => { const limit = usage?.rateLimits?.[window]; return <React.Fragment key={window}><Detail label={`${words(window)} window used`}>{numeric(limit?.usedPercent) ? `${limit.usedPercent}%${numeric(limit.windowMinutes) ? ` · ${limit.windowMinutes.toLocaleString()} min window` : ''}` : 'Unavailable'}</Detail><Detail label={`${words(window)} reset`}>{dateTime(limit?.resetAt)}</Detail></React.Fragment>; })}<p className="panel-copy">Reported usage windows are not a remaining-token balance. Observed {timeAgo(usage?.rateLimits?.collectedAt).toLowerCase()}.</p><div className="allowance-note"><ShieldCheck size={23} /><strong>No additional spending authorized</strong><p>Recorded tokens measure activity. They do not reveal remaining subscription credits or authorize top-ups.</p></div></Panel></div><Panel title="Usage attribution" subtitle="Cached and reasoning tokens remain subsets; overlapping collectors must not be added" action={<div className="segmented">{(['Turn', 'Session', 'Task', 'Agent'] as const).map(value => <button key={value} className={tab === value ? 'selected' : ''} onClick={() => setTab(value)}>{value}</button>)}</div>}><UsageTable label={tab} rows={tab === 'Turn' ? usage?.byTurn : tab === 'Session' ? usage?.bySession : tab === 'Task' ? usage?.byTask : usage?.byAgent} /></Panel><Panel title="Telemetry provenance" subtitle={`Last collected ${timeAgo(data.coverage?.collectedAt).toLowerCase()}`}><div className="provenance-grid">{data.coverage?.sources?.length ? data.coverage.sources.map((source, index) => <div className="provenance-source" key={index}><Database size={18} /><div><strong>{words(source.kind)}</strong><small>{numeric(source.files) ? `${source.files} retained files` : 'File count unavailable'}</small></div><Badge status={source.status} /></div>) : <Empty title="Collection provenance unavailable" />}</div>{data.coverage?.warnings?.map((warning, index) => <Note key={index} warning>{warning}</Note>)}{Boolean(data.coverage?.metricsUnavailable?.length) && <p className="panel-copy"><strong>Unavailable metrics:</strong> {data.coverage?.metricsUnavailable?.map(words).join(', ')}.</p>}</Panel></>; }

function ApprovalsView({ approvals, allowed, control }: { approvals: Approval[] } & ControlProps) { const [selected, setSelected] = useState<Approval | null>(null), [decision, setDecision] = useState<'approve' | 'reject'>('approve'), [confirmed, setConfirmed] = useState(false), [typed, setTyped] = useState(''), [expiry, setExpiry] = useState(''), [validation, setValidation] = useState(''); const close = useCallback(() => { setSelected(null); setValidation(''); }, []); const pending = approvals.filter(row => row.status === 'pending'), resolved = approvals.filter(row => row.status !== 'pending'); function choose(row: Approval, next: 'approve' | 'reject') { setSelected(row); setDecision(next); setConfirmed(false); setTyped(''); setExpiry(''); setValidation(''); } return <><Note>Approval records a human decision for an exact reviewed action. It does not activate scheduling, run a migration, or deploy a backfill.</Note>{!approvals.length ? <Panel title="Approval inbox"><Empty icon={ShieldCheck} title="No approval records">Prepared proposals will appear here when owner review is required.</Empty></Panel> : <><div className="approval-grid">{pending.map(row => <section className="approval-card" key={row.id}><div className="approval-card-top"><span className="approval-shield"><ShieldCheck size={21} /></span><Badge status="pending" label="Owner decision" /></div><span className="task-id">{row.id}</span><h2>{row.exact_proposed_action ?? 'Proposed action not reported'}</h2><p>{row.why_approval_required ?? 'Review the proposal and its exact target before deciding.'}</p><div className="approval-meta"><Fingerprint size={14} />{row.stale ? 'Source changed · prepare a fresh review' : sha(row.target_fingerprint) && sha(row.task_fingerprint) ? 'Exact fingerprints bound' : 'Exact target not yet prepared'}</div><div className="button-row"><button className="button button-primary" disabled={!allowed('approve') || row.stale === true || !sha(row.target_fingerprint) || !sha(row.task_fingerprint)} onClick={() => choose(row, 'approve')}>Review approval <ArrowRight size={14} /></button><button className="button" disabled={!allowed('reject')} onClick={() => choose(row, 'reject')}>Reject</button></div></section>)}</div>{!pending.length && <Panel title="Pending decisions"><Empty icon={CheckCheck} title="No pending approval records" /></Panel>}{resolved.length > 0 && <Panel title="Decision history" subtitle="Persisted owner decisions, not inferred authorizations"><div className="table-scroll"><table><thead><tr><th>Proposal</th><th>Decision</th><th>Recorded</th><th>Expiration</th></tr></thead><tbody>{resolved.map(row => <tr key={row.id}><td><span className="task-id">{row.id}</span><strong className="table-task-title">{row.exact_proposed_action}</strong></td><td><Badge status={row.status} /></td><td>{dateTime(row.decision?.recorded_at)}</td><td>{dateTime(row.expires_at)}</td></tr>)}</tbody></table></div></Panel>}</>}{selected && <Modal title={decision === 'approve' ? 'Review exact approval' : 'Reject this proposal'} close={close}><span className="task-id">{selected.id}</span><h3>{selected.exact_proposed_action}</h3><p className="modal-description">{selected.expected_consequences ?? selected.why_approval_required}</p><div className="fingerprint-box"><label>Target fingerprint</label><code>{selected.target_fingerprint ?? 'Not prepared'}</code><label>Task fingerprint</label><code>{selected.task_fingerprint ?? 'Not prepared'}</code></div>{Boolean(selected.affected_resources?.length) && <p className="panel-copy"><strong>Affected resources:</strong> {selected.affected_resources?.join(', ')}</p>}{selected.recommendation && <Note>{selected.recommendation}</Note>}<form className="stacked-form" onSubmit={async event => { event.preventDefault(); if (decision === 'approve' && selected.stale) { setValidation('This proposal is stale. A fresh exact review is required.'); return; } if (!confirmed || typed !== selected.id) { setValidation('Confirm the exact proposal and type its approval ID.'); return; } if (decision === 'approve' && (!expiry || !Number.isFinite(Date.parse(expiry)) || Date.parse(expiry) <= Date.now())) { setValidation('Choose an explicit expiration in the future.'); return; } const ok = await control(decision, { approvalId: selected.id, targetFingerprint: selected.target_fingerprint, taskFingerprint: selected.task_fingerprint, confirmed: true, ...(decision === 'approve' ? { expiresAt: new Date(expiry).toISOString() } : {}) }); if (ok) close(); }}>
          {decision === 'approve' && <><label htmlFor="approval-expiry">Approval expires</label><input id="approval-expiry" type="datetime-local" value={expiry} onChange={event => setExpiry(event.target.value)} required /></>}
          <label htmlFor="approval-confirm-id">Type {selected.id} to confirm</label><input id="approval-confirm-id" value={typed} onChange={event => setTyped(event.target.value)} autoComplete="off" required /><label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} /><span>I reviewed this exact action and its target and task fingerprints. This {decision === 'approve' ? 'approval' : 'rejection'} applies only to this proposal.</span></label>{validation && <div className="form-error" role="alert">{validation}</div>}<div className="modal-actions"><button type="button" className="button" onClick={close}>Cancel</button><button className={`button ${decision === 'approve' ? 'button-primary' : 'button-danger'}`} disabled={!confirmed || typed !== selected.id || !allowed(decision) || (decision === 'approve' && selected.stale === true)}>{decision === 'approve' ? <><Check size={16} /> Record exact approval</> : <><XCircle size={16} /> Record rejection</>}</button></div></form></Modal>}</>; }

function GitView({ data }: { data: State }) { const git = data.git; const checkpoint = typeof git?.lastCheckpoint === 'string' ? git.lastCheckpoint : git?.lastCheckpoint?.commit; return <><div className="metrics-grid"><Metric label="Current branch" value={git?.branch ?? 'Unavailable'} detail="Observed local repository" icon={GitBranch} /><Metric label="Current commit" value={git?.commit ? short(git.commit, 10) : 'Unavailable'} detail="Exact local checkpoint reference" icon={FileCheck2} /><Metric label="Ahead / behind" value={numeric(git?.ahead) && numeric(git?.behind) ? `${git.ahead} / ${git.behind}` : 'Unavailable'} detail="Local upstream tracking refs; not a fresh fetch" icon={ArrowUpRight} /><Metric label="Working tree" value={git?.dirty === true ? 'Changes present' : git?.dirty === false ? 'Clean' : 'Unavailable'} detail="No automatic resets or overwrites" icon={ShieldCheck} /></div><Panel title="Recorded verification" subtitle="Existing test evidence only; opening this page does not run a suite"><div className="table-scroll"><table><thead><tr><th>Check</th><th>Recorded status</th><th>Count</th><th>Evidence source</th></tr></thead><tbody>{git?.tests?.map((test, index) => <tr key={index}><td><strong>{test.name}</strong></td><td><Badge status={test.status} /></td><td>{count(test.count)}</td><td className="mono muted">{test.source ?? 'Not reported'}</td></tr>)}</tbody></table>{!git?.tests?.length && <Empty icon={FileCheck2} title="No test evidence collected">No passing checks are inferred from the current commit.</Empty>}</div></Panel><Panel title="Checkpoint and integration"><div className="detail-grid"><Detail label="Last reported checkpoint"><code>{checkpoint ?? 'Unavailable'}</code></Detail><Detail label="Integration authority">Reviewed main integration only</Detail><Detail label="Force push">Not permitted</Detail><Detail label="Automatic writable execution">{data.capabilities?.writableExecution ? 'See approved policy' : 'Not enabled'}</Detail></div></Panel></>; }

function InfrastructureView({ data }: { data: State }) { const info = data.infrastructure; const sampled = info?.sampledAt, stale = Boolean(sampled && Date.parse(data.generatedAt) - Date.parse(sampled) > 60000); return <><div className="observation-line"><span><Clock3 size={15} /> Sampled {timeAgo(sampled).toLowerCase()}</span>{stale && <Badge status="stale" />}</div><div className="metrics-grid"><Metric label="Host uptime" value={duration(info?.hostUptimeSeconds)} detail="Observed on this host" icon={Clock3} /><Metric label="CPU utilization" value={numeric(info?.cpuPercent) ? `${info.cpuPercent.toFixed(1)}%` : 'Unavailable'} detail="No estimate from agent counts" icon={Cpu} /><Metric label="Memory used" value={numeric(info?.memory?.percent) ? `${info.memory.percent.toFixed(1)}%` : 'Unavailable'} detail={`${bytes(info?.memory?.usedBytes)} / ${bytes(info?.memory?.totalBytes)}`} icon={Server} /><Metric label="Disk free" value={bytes(info?.disk?.freeBytes)} detail={`Capacity ${bytes(info?.disk?.totalBytes)}`} icon={HardDrive} /></div><div className="service-grid">{[{ name: 'Internet connectivity', icon: Wifi, state: info?.internet?.state, detail: `Observed ${timeAgo(info?.internet?.observedAt).toLowerCase()}` }, { name: 'Codex CLI', icon: Terminal, state: info?.codex?.available === true ? 'available' : info?.codex?.available === false ? 'offline' : null, detail: info?.codex?.version ?? 'Version unavailable' }, { name: 'PostgreSQL', icon: Database, state: info?.postgres?.state, detail: 'Health signal only; no data browser' }, { name: 'Fantasy Evolution', icon: LayoutDashboard, state: info?.application?.state, detail: 'Independent application health' }, { name: 'Managed workers', icon: ActivityIcon, state: info?.workers?.state, detail: 'Supervisor presence only; individual worker health unavailable' }, { name: 'Scheduler', icon: Clock3, state: info?.scheduler?.state, detail: 'No activation control is exposed' }].map(({ name, icon: Icon, state, detail }) => <div className="service-card" key={name}><div><span className="service-icon"><Icon size={21} /></span><Badge status={state} /></div><h3>{name}</h3><p>{detail}</p></div>)}</div><Note>The local dashboard can remain available when internet access is lost. Missing service metrics are marked unavailable; stale readings are not treated as current health.</Note></>; }

function SettingsView({ data, allowed, control }: { data: State } & ControlProps) { const [limit, setLimit] = useState(String(data.automation?.max_specialists ?? '')); return <><div className="two-column"><Panel title="Execution policy" subtitle="Limits are configured authority, not observed activity"><Detail label="Current mode"><Badge status={data.automation?.mode} /></Detail><Detail label="Writable execution">{data.capabilities?.writableExecution ? 'See approved policy' : 'Not enabled'}</Detail><Detail label="Daily reserved attempts">{count(data.settings?.maxDailyAttempts)}</Detail>{data.settings?.usageGuard && <Note warning>{data.settings.usageGuard.reason ?? 'Usage guard active'}. Next eligibility: {typeof data.settings.usageGuard.nextAttemptAt === 'number' ? dateTime(new Date(data.settings.usageGuard.nextAttemptAt).toISOString()) : 'Unavailable'}. No credit purchase or top-up is authorized.</Note>}<Detail label="Maximum attempts per task">{count(data.settings?.maxAttempts)}</Detail><Detail label="Bounded execution timeout">{duration(data.settings?.executionTimeoutSeconds)}</Detail><form className="stacked-form" onSubmit={event => { event.preventDefault(); void control('concurrency', { limit: Number(limit) }); }}><label htmlFor="concurrency">Configured specialist limit <span>Maximum three</span></label><div className="input-action"><select id="concurrency" required value={limit} onChange={event => setLimit(event.target.value)}><option value="" disabled>Unavailable</option>{[1, 2, 3].map(value => <option key={value} value={value}>{value} specialist{value > 1 ? 's' : ''}</option>)}</select><button className="button" disabled={!allowed('concurrency') || !limit}>Save limit</button></div><small className="muted">This does not create agents or enable writable work.</small></form></Panel><Panel title="Zero additional spending" subtitle="This application cannot enforce spending across an entire account"><div className="policy-amount">$0<span>Additional spending authorization</span></div><Detail label="Authentication">{data.settings?.authentication ?? 'Unavailable'}</Detail><Detail label="API billing fallback">{data.settings?.apiBillingFallback === false ? 'Disabled' : 'Unavailable'}</Detail><Detail label="Automatic top-ups">Not configured</Detail><Detail label="Subscription balance">{count(data.usage?.subscriptionRemaining)}</Detail><Note>New AI work must pause when a usage limit is observed. A local token ledger is not an allowance balance.</Note></Panel><Panel title="Local access and persistence"><Detail label="Listen address">{data.settings?.host && data.settings?.port ? `${data.settings.host}:${data.settings.port}` : 'Unavailable'}</Detail><Detail label="Control authentication">HttpOnly local session</Detail><Detail label="Request protection">CSRF token required</Detail><Detail label="History import">{data.coverage?.historyEnabled === true ? 'Enabled · read-only collection' : data.coverage?.historyEnabled === false ? 'Disabled' : 'Unavailable'}</Detail><Detail label="Collector coverage">{dateTime(data.coverage?.collectedAt)}</Detail>{data.coverage?.historyEnabled !== true && <div className="history-opt-in"><p>Optionally inspect bounded local Codex history for recorded usage. No model call or database change.</p><button className="button" disabled={!allowed('importHistory')} onClick={() => { if (window.confirm('Enable bounded read-only local history collection? Session text and credentials are excluded from the dashboard.')) void control('importHistory', { confirmed: true }); }}>Import local usage history</button></div>}</Panel><Panel title="Unattended scheduling"><div className="scheduler-lock"><LockKeyhole size={25} /><h3>Separate approval required</h3><p>The dashboard can record an exact owner decision. It does not install or activate an unattended scheduler.</p><Badge status={data.infrastructure?.scheduler?.state} /></div><Note>Implementation work, main integration, migrations and operational backfills remain subject to their existing safeguards.</Note></Panel></div></>; }
